using System;
using System.Collections;
using UnityEngine;

public static class SpriteRendererExtensions
{
	public static void SetAlpha(this SpriteRenderer render, float alpha)
	{
		render.color = render.color.SetAlpha(alpha);
	}

	public static IEnumerator FadeSprite(this SpriteRenderer renderer, float targetAlpha, float duration, AnimationCurve curve)
	{
		float startingAlpha = renderer.Alpha();
		return CoroutineUtility.CurveRoutine(duration, curve, delegate(float t, float v)
		{
			renderer.SetAlpha(Mathf.Lerp(startingAlpha, targetAlpha, v));
		});
	}

	public static IEnumerator FadeSprite(this SpriteRenderer renderer, float targetAlpha, float duration, AnimationCurve curve, Action endAction)
	{
		float startingAlpha = renderer.Alpha();
		return CoroutineUtility.CurveRoutine(duration, curve, delegate(float t, float v)
		{
			renderer.SetAlpha(Mathf.Lerp(startingAlpha, targetAlpha, v));
		}, endAction);
	}

	public static IEnumerator FadeSprite(this SpriteRenderer renderer, float targetAlpha, float duration)
	{
		float startingAlpha = renderer.Alpha();
		return CoroutineUtility.CurveRoutine(duration, delegate(float t, float v)
		{
			renderer.SetAlpha(Mathf.Lerp(startingAlpha, targetAlpha, v));
		});
	}

	public static IEnumerator FadeSprite(this SpriteRenderer renderer, float targetAlpha, float duration, Action endAction)
	{
		float startingAlpha = renderer.Alpha();
		return CoroutineUtility.CurveRoutine(duration, delegate(float t, float v)
		{
			renderer.SetAlpha(Mathf.Lerp(startingAlpha, targetAlpha, v));
		}, endAction);
	}

	public static IEnumerator BlinkSprite(this SpriteRenderer renderer, float targetAlpha, float duration, int cycles)
	{
		float startingAlpha = renderer.Alpha();
		AnimationCurve curve = new AnimationCurve();
		curve.AddKey(0f, 0f);
		curve.AddKey(0.5f, 1f);
		curve.AddKey(1f, 0f);
		for (int i = 0; i < cycles; i++)
		{
			yield return CoroutineUtility.CurveRoutine(duration, curve, delegate(float t, float v)
			{
				renderer.SetAlpha(Mathf.Lerp(startingAlpha, targetAlpha, v));
			});
		}
	}

	public static float Alpha(this SpriteRenderer renderer)
	{
		return renderer.color.a;
	}
}
